  const factor = d.fromFactor !== d.toFactor ? `${chalk.dim(fmtFactor(d.fromFactor))} \u2192 ${chalk.yellow(fmtFactor(d.toFactor))}` : chalk.dim(fmtFactor(d.toFactor));
